// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strncasecmp() from lib/string.c.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/ctype.h>

/*
 * Helper macros that check only the sign of the result, which is the
 * portable contract of strncasecmp().
 */
#define EXPECT_LT_ZERO(test, expr) KUNIT_EXPECT_LT(test, (expr), 0)
#define EXPECT_GT_ZERO(test, expr) KUNIT_EXPECT_GT(test, (expr), 0)
#define EXPECT_ZERO(test, expr)    KUNIT_EXPECT_EQ(test, (expr), 0)

static void agent_test_identical_strings(struct kunit *test)
{
	EXPECT_ZERO(test, strncasecmp("hello", "hello", 5));
	EXPECT_ZERO(test, strncasecmp("hello", "hello", 6));
	EXPECT_ZERO(test, strncasecmp("hello", "hello", 100));
	EXPECT_ZERO(test, strncasecmp("a", "a", 1));
	EXPECT_ZERO(test, strncasecmp("a", "a", SIZE_MAX));
}

static void agent_test_case_insensitive_equal(struct kunit *test)
{
	EXPECT_ZERO(test, strncasecmp("hello", "HELLO", 5));
	EXPECT_ZERO(test, strncasecmp("HeLLo", "hElLO", 5));
	EXPECT_ZERO(test, strncasecmp("Linux", "LINUX", 10));
	EXPECT_ZERO(test, strncasecmp("abcdefghijklmnopqrstuvwxyz",
				      "ABCDEFGHIJKLMNOPQRSTUVWXYZ", 26));
	EXPECT_ZERO(test, strncasecmp("ABCDEFGHIJKLMNOPQRSTUVWXYZ",
				      "abcdefghijklmnopqrstuvwxyz", 26));
	/* Non-letters must compare exactly, mixed with letters. */
	EXPECT_ZERO(test, strncasecmp("a1-B2_c3", "A1-b2_C3", 8));
	EXPECT_ZERO(test, strncasecmp("Hello, World!", "hELLO, wORLD!", 13));
}

static void agent_test_empty_strings(struct kunit *test)
{
	EXPECT_ZERO(test, strncasecmp("", "", 0));
	EXPECT_ZERO(test, strncasecmp("", "", 1));
	EXPECT_ZERO(test, strncasecmp("", "", 100));
	/* Empty vs non-empty: the empty one is "less". */
	EXPECT_LT_ZERO(test, strncasecmp("", "a", 1));
	EXPECT_GT_ZERO(test, strncasecmp("a", "", 1));
	EXPECT_LT_ZERO(test, strncasecmp("", "A", 5));
	EXPECT_GT_ZERO(test, strncasecmp("A", "", 5));
	/* Exact value: terminator (0) vs 'a' (97). */
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 3), -'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 3), 'a');
}

static void agent_test_zero_length(struct kunit *test)
{
	/* With len == 0 nothing is compared; always equal. */
	EXPECT_ZERO(test, strncasecmp("abc", "xyz", 0));
	EXPECT_ZERO(test, strncasecmp("xyz", "abc", 0));
	EXPECT_ZERO(test, strncasecmp("a", "", 0));
	EXPECT_ZERO(test, strncasecmp("", "a", 0));
	EXPECT_ZERO(test, strncasecmp("ABC", "abd", 0));
}

static void agent_test_length_one(struct kunit *test)
{
	EXPECT_ZERO(test, strncasecmp("a", "A", 1));
	EXPECT_ZERO(test, strncasecmp("ab", "AC", 1));
	EXPECT_LT_ZERO(test, strncasecmp("a", "b", 1));
	EXPECT_GT_ZERO(test, strncasecmp("b", "a", 1));
	EXPECT_LT_ZERO(test, strncasecmp("A", "b", 1));
	EXPECT_GT_ZERO(test, strncasecmp("B", "a", 1));
}

static void agent_test_length_limits_comparison(struct kunit *test)
{
	/* Differences beyond len must be ignored. */
	EXPECT_ZERO(test, strncasecmp("abcX", "ABCY", 3));
	EXPECT_ZERO(test, strncasecmp("abcdef", "ABCxyz", 3));
	EXPECT_ZERO(test, strncasecmp("abc", "abcdef", 3));
	EXPECT_ZERO(test, strncasecmp("abcdef", "abc", 3));
	EXPECT_ZERO(test, strncasecmp("hello world", "HELLO there", 6));

	/* Differences exactly at position len-1 must be seen (off-by-one). */
	EXPECT_LT_ZERO(test, strncasecmp("abcX", "ABCY", 4));
	EXPECT_GT_ZERO(test, strncasecmp("abcY", "ABCX", 4));
	EXPECT_LT_ZERO(test, strncasecmp("aab", "aac", 3));
	EXPECT_GT_ZERO(test, strncasecmp("aac", "aab", 3));

	/* Differences at position len must NOT be seen. */
	EXPECT_ZERO(test, strncasecmp("aab", "aac", 2));
	EXPECT_ZERO(test, strncasecmp("aac", "aab", 2));

	/* Difference at position 0 is always seen when len >= 1. */
	EXPECT_LT_ZERO(test, strncasecmp("abc", "bbc", 1));
	EXPECT_GT_ZERO(test, strncasecmp("bbc", "abc", 1));
}

static void agent_test_first_char_differs(struct kunit *test)
{
	EXPECT_LT_ZERO(test, strncasecmp("apple", "banana", 5));
	EXPECT_GT_ZERO(test, strncasecmp("banana", "apple", 5));
	EXPECT_LT_ZERO(test, strncasecmp("Apple", "banana", 5));
	EXPECT_GT_ZERO(test, strncasecmp("Banana", "apple", 5));
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "c", 1), 'a' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("C", "a", 1), 'c' - 'a');
}

static void agent_test_middle_char_differs(struct kunit *test)
{
	EXPECT_LT_ZERO(test, strncasecmp("abcde", "abXde", 5));
	EXPECT_GT_ZERO(test, strncasecmp("abXde", "abcde", 5));
	EXPECT_LT_ZERO(test, strncasecmp("ABCDE", "abxde", 5));
	EXPECT_GT_ZERO(test, strncasecmp("abxde", "ABCDE", 5));
	/* Exact value: lowered difference. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abC", "abd", 3), 'c' - 'd');
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abC", 3), 'd' - 'c');
}

static void agent_test_last_char_differs(struct kunit *test)
{
	EXPECT_LT_ZERO(test, strncasecmp("abcd", "abce", 4));
	EXPECT_GT_ZERO(test, strncasecmp("abce", "abcd", 4));
	EXPECT_LT_ZERO(test, strncasecmp("ABCD", "abce", 4));
	EXPECT_GT_ZERO(test, strncasecmp("abce", "ABCD", 4));
	/* Larger len than the strings still finds the last difference. */
	EXPECT_LT_ZERO(test, strncasecmp("abcd", "abce", 100));
	EXPECT_GT_ZERO(test, strncasecmp("abce", "abcd", 100));
}

static void agent_test_prefix_strings(struct kunit *test)
{
	/* Shorter string is a prefix of the longer: shorter is "less". */
	EXPECT_LT_ZERO(test, strncasecmp("abc", "abcd", 4));
	EXPECT_GT_ZERO(test, strncasecmp("abcd", "abc", 4));
	EXPECT_LT_ZERO(test, strncasecmp("ABC", "abcd", 10));
	EXPECT_GT_ZERO(test, strncasecmp("abcd", "ABC", 10));
	EXPECT_LT_ZERO(test, strncasecmp("abc", "ABCD", 4));

	/* Terminator vs 'd' at index 3 - exact values. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 4), -'d');
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abc", 4), 'd');

	/* With len equal to the prefix length they compare equal. */
	EXPECT_ZERO(test, strncasecmp("abc", "abcd", 3));
	EXPECT_ZERO(test, strncasecmp("abcd", "abc", 3));
	EXPECT_ZERO(test, strncasecmp("ABC", "abcd", 3));
}

static void agent_test_stops_at_nul(struct kunit *test)
{
	/* Bytes after the terminator must never be examined. */
	static const char a[] = { 'a', 'b', '\0', 'x', 'y', 'z', '\0' };
	static const char b[] = { 'A', 'B', '\0', 'q', 'r', 's', '\0' };
	static const char c[] = { 'a', 'b', '\0', '\0', '\0', '\0', '\0' };

	EXPECT_ZERO(test, strncasecmp(a, b, sizeof(a)));
	EXPECT_ZERO(test, strncasecmp(b, a, sizeof(a)));
	EXPECT_ZERO(test, strncasecmp(a, c, sizeof(a)));
	EXPECT_ZERO(test, strncasecmp(a, b, 1000));
}

static void agent_test_non_alpha_chars(struct kunit *test)
{
	/* Digits and punctuation are not case-folded. */
	EXPECT_ZERO(test, strncasecmp("12345", "12345", 5));
	EXPECT_LT_ZERO(test, strncasecmp("12345", "12346", 5));
	EXPECT_GT_ZERO(test, strncasecmp("12346", "12345", 5));
	EXPECT_ZERO(test, strncasecmp("!@#$%", "!@#$%", 5));
	EXPECT_LT_ZERO(test, strncasecmp("!@#$%", "!@#$^", 5));
	EXPECT_ZERO(test, strncasecmp("a b\tc\n", "A B\tC\n", 6));
	EXPECT_LT_ZERO(test, strncasecmp("a b", "a\tb", 3));
	/* Letters vs digits: 'a' (97) > '1' (49) */
	EXPECT_GT_ZERO(test, strncasecmp("a", "1", 1));
	EXPECT_GT_ZERO(test, strncasecmp("A", "1", 1));
	EXPECT_LT_ZERO(test, strncasecmp("1", "a", 1));
	EXPECT_LT_ZERO(test, strncasecmp("1", "A", 1));
}

static void agent_test_ascii_neighbors_of_letters(struct kunit *test)
{
	/*
	 * Characters adjacent to the letter ranges in ASCII must not be
	 * treated as letters: '@' (0x40) precedes 'A', '[' (0x5b) follows
	 * 'Z', '`' (0x60) precedes 'a', '{' (0x7b) follows 'z'.
	 */
	KUNIT_EXPECT_NE(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("`", "@", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("{", "[", 1), 0);
	/* But the real letter range boundaries are folded. */
	EXPECT_ZERO(test, strncasecmp("A", "a", 1));
	EXPECT_ZERO(test, strncasecmp("Z", "z", 1));
	EXPECT_ZERO(test, strncasecmp("a", "A", 1));
	EXPECT_ZERO(test, strncasecmp("z", "Z", 1));
	/* 'Z' vs 'a' are different letters even after folding. */
	EXPECT_GT_ZERO(test, strncasecmp("Z", "a", 1));
	EXPECT_LT_ZERO(test, strncasecmp("a", "Z", 1));
}

static void agent_test_case_folding_order(struct kunit *test)
{
	/*
	 * Ordering must be computed on the folded values, so that an upper
	 * case letter compares the same as its lower case counterpart.
	 * Raw 'B' (66) < raw 'a' (97), but folded 'b' > 'a'.
	 */
	EXPECT_GT_ZERO(test, strncasecmp("B", "a", 1));
	EXPECT_LT_ZERO(test, strncasecmp("a", "B", 1));
	EXPECT_GT_ZERO(test, strncasecmp("Zebra", "apple", 5));
	EXPECT_LT_ZERO(test, strncasecmp("apple", "ZEBRA", 5));
	/* Exact folded difference. */
	KUNIT_EXPECT_EQ(test, strncasecmp("B", "a", 1), 'b' - 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "B", 1), 'a' - 'b');
	KUNIT_EXPECT_EQ(test, strncasecmp("xyZ", "XYa", 3), 'z' - 'a');
}

static void agent_test_high_bytes_unsigned(struct kunit *test)
{
	/* Bytes >= 0x80 must be compared as unsigned (greater than ASCII). */
	static const char hi[] = { (char)0xff, '\0' };
	static const char hi2[] = { (char)0x80, '\0' };
	static const char lo[] = { 'a', '\0' };
	static const char nul[] = { '\0' };

	EXPECT_GT_ZERO(test, strncasecmp(hi, lo, 1));
	EXPECT_LT_ZERO(test, strncasecmp(lo, hi, 1));
	EXPECT_GT_ZERO(test, strncasecmp(hi2, lo, 1));
	EXPECT_LT_ZERO(test, strncasecmp(lo, hi2, 1));
	EXPECT_GT_ZERO(test, strncasecmp(hi, hi2, 1));
	EXPECT_LT_ZERO(test, strncasecmp(hi2, hi, 1));
	EXPECT_ZERO(test, strncasecmp(hi, hi, 1));
	EXPECT_ZERO(test, strncasecmp(hi2, hi2, 5));
	/* High byte vs terminator: high byte is greater. */
	EXPECT_GT_ZERO(test, strncasecmp(hi, nul, 1));
	EXPECT_LT_ZERO(test, strncasecmp(nul, hi, 1));
	/* Exact unsigned values. */
	KUNIT_EXPECT_EQ(test, strncasecmp(hi, lo, 1), 0xff - 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp(hi, nul, 1), 0xff);
}

static void agent_test_high_bytes_not_folded(struct kunit *test)
{
	/* 0xc1 and 0xe1 differ by 0x20 like 'A'/'a' but are not letters. */
	static const char s1[] = { (char)0xc1, '\0' };
	static const char s2[] = { (char)0xe1, '\0' };

	KUNIT_EXPECT_NE(test, strncasecmp(s1, s2, 1), 0);
	EXPECT_LT_ZERO(test, strncasecmp(s1, s2, 1));
	EXPECT_GT_ZERO(test, strncasecmp(s2, s1, 1));
}

static void agent_test_long_strings(struct kunit *test)
{
	char *a, *b;
	size_t i, n = 1024;

	a = kunit_kzalloc(test, n + 1, GFP_KERNEL);
	b = kunit_kzalloc(test, n + 1, GFP_KERNEL);
	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, a);
	KUNIT_ASSERT_NOT_ERR_OR_NULL(test, b);

	for (i = 0; i < n; i++) {
		a[i] = 'a' + (i % 26);
		b[i] = 'A' + (i % 26);
	}

	EXPECT_ZERO(test, strncasecmp(a, b, n));
	EXPECT_ZERO(test, strncasecmp(a, b, n + 1));
	EXPECT_ZERO(test, strncasecmp(a, b, n * 4));
	EXPECT_ZERO(test, strncasecmp(b, a, n));

	/* Change the very last byte. */
	b[n - 1] = '~';
	EXPECT_LT_ZERO(test, strncasecmp(a, b, n));
	EXPECT_GT_ZERO(test, strncasecmp(b, a, n));
	EXPECT_ZERO(test, strncasecmp(a, b, n - 1));
	b[n - 1] = 'A' + ((n - 1) % 26);
	EXPECT_ZERO(test, strncasecmp(a, b, n));

	/* Truncate b so it is a prefix of a. */
	b[n / 2] = '\0';
	EXPECT_GT_ZERO(test, strncasecmp(a, b, n));
	EXPECT_LT_ZERO(test, strncasecmp(b, a, n));
	EXPECT_ZERO(test, strncasecmp(a, b, n / 2));
}

static void agent_test_antisymmetry_all_bytes(struct kunit *test)
{
	/*
	 * For every pair of non-NUL bytes, result(x, y) must have the
	 * opposite sign of result(y, x), and must be zero exactly when the
	 * bytes are equal or are the two cases of the same ASCII letter.
	 */
	char s1[2] = { 0, 0 };
	char s2[2] = { 0, 0 };
	unsigned int x, y;

	for (x = 1; x < 256; x++) {
		for (y = 1; y < 256; y++) {
			int r1, r2;
			bool same;

			s1[0] = (char)x;
			s2[0] = (char)y;
			r1 = strncasecmp(s1, s2, 1);
			r2 = strncasecmp(s2, s1, 1);

			same = (x == y) ||
			       (isalpha(x) && isalpha(y) &&
				tolower(x) == tolower(y));

			if (same) {
				KUNIT_EXPECT_EQ_MSG(test, r1, 0,
						    "x=%#x y=%#x", x, y);
				KUNIT_EXPECT_EQ_MSG(test, r2, 0,
						    "x=%#x y=%#x", x, y);
			} else {
				KUNIT_EXPECT_NE_MSG(test, r1, 0,
						    "x=%#x y=%#x", x, y);
				KUNIT_EXPECT_TRUE_MSG(test,
						      (r1 < 0) == (r2 > 0),
						      "x=%#x y=%#x r1=%d r2=%d",
						      x, y, r1, r2);
			}
		}
	}
}

static void agent_test_consistent_with_strcasecmp(struct kunit *test)
{
	/* With len >= both lengths, strncasecmp must agree with strcasecmp. */
	static const char * const strs[] = {
		"", "a", "A", "abc", "ABC", "abd", "abcd", "Hello", "hello!",
		"zzz", "ZZZ", "123", "a1", "A2",
	};
	unsigned int i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			int n = strncasecmp(strs[i], strs[j], 64);
			int s = strcasecmp(strs[i], strs[j]);

			KUNIT_EXPECT_EQ_MSG(test, (n > 0) - (n < 0),
					    (s > 0) - (s < 0),
					    "\"%s\" vs \"%s\"",
					    strs[i], strs[j]);
		}
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_identical_strings),
	KUNIT_CASE(agent_test_case_insensitive_equal),
	KUNIT_CASE(agent_test_empty_strings),
	KUNIT_CASE(agent_test_zero_length),
	KUNIT_CASE(agent_test_length_one),
	KUNIT_CASE(agent_test_length_limits_comparison),
	KUNIT_CASE(agent_test_first_char_differs),
	KUNIT_CASE(agent_test_middle_char_differs),
	KUNIT_CASE(agent_test_last_char_differs),
	KUNIT_CASE(agent_test_prefix_strings),
	KUNIT_CASE(agent_test_stops_at_nul),
	KUNIT_CASE(agent_test_non_alpha_chars),
	KUNIT_CASE(agent_test_ascii_neighbors_of_letters),
	KUNIT_CASE(agent_test_case_folding_order),
	KUNIT_CASE(agent_test_high_bytes_unsigned),
	KUNIT_CASE(agent_test_high_bytes_not_folded),
	KUNIT_CASE(agent_test_long_strings),
	KUNIT_CASE(agent_test_antisymmetry_all_bytes),
	KUNIT_CASE(agent_test_consistent_with_strcasecmp),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit test for strncasecmp()");
MODULE_LICENSE("GPL");

