// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strcspn() from lib/string.c:
 *
 *   size_t strcspn(const char *s, const char *reject);
 *
 * Returns the length of the initial segment of @s consisting entirely of
 * bytes NOT in @reject. The terminating NUL of @s is never counted and is
 * never considered a member of @reject.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/types.h>

/* ---- Degenerate / boundary inputs --------------------------------------- */

static void strcspn_empty_string_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
}

static void strcspn_empty_string_nonempty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", "abcxyz"), (size_t)0);
}

static void strcspn_nonempty_string_empty_reject(struct kunit *test)
{
	/* Nothing is rejected, so the whole string is the span. */
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), strlen("hello"));
	KUNIT_EXPECT_EQ(test, strcspn("hello world", ""), (size_t)11);
}

static void strcspn_single_char_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "xa"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "ax"), (size_t)0);
}

static void strcspn_single_char_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("a", "bcdef"), (size_t)1);
}

/* ---- Position of the first rejected byte -------------------------------- */

static void strcspn_reject_at_first_position(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "h"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "zyh"), (size_t)0);
}

static void strcspn_reject_at_second_position(struct kunit *test)
{
	/* Off-by-one guard: result must be exactly 1, not 0 or 2. */
	KUNIT_EXPECT_EQ(test, strcspn("hello", "e"), (size_t)1);
}

static void strcspn_reject_in_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "l"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "d"), (size_t)3);
}

static void strcspn_reject_at_last_position(struct kunit *test)
{
	/* Last byte matches: span is len - 1. */
	KUNIT_EXPECT_EQ(test, strcspn("hello", "o"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "f"), (size_t)5);
}

static void strcspn_no_reject_found(struct kunit *test)
{
	/* No byte matches: span is the full length, not len - 1 or len + 1. */
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "HELLO"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "g"), strlen("abcdef"));
}

/* ---- Set semantics of @reject ------------------------------------------- */

static void strcspn_first_of_many_rejects_wins(struct kunit *test)
{
	/*
	 * Multiple reject characters appear in the string; the result is the
	 * index of whichever occurs first in @s, regardless of order in @reject.
	 */
	KUNIT_EXPECT_EQ(test, strcspn("hello", "ol"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "lo"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "oe"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "cb"), (size_t)1);
}

static void strcspn_reject_order_irrelevant(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fedcba"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyzc"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "cxyz"), (size_t)2);
}

static void strcspn_duplicate_reject_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "lll"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xxoxx"), (size_t)4);
}

static void strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "h"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "H"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "L"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("heLlo", "L"), (size_t)2);
}

static void strcspn_repeated_chars_in_string(struct kunit *test)
{
	/* The first occurrence counts, not the last. */
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("baaa", "a"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("bbba", "a"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("mississippi", "s"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("mississippi", "p"), (size_t)8);
}

/* ---- NUL handling ------------------------------------------------------- */

static void strcspn_nul_is_not_a_reject_member(struct kunit *test)
{
	/*
	 * A naive implementation using strchr(reject, c) without excluding
	 * '\0' would treat the string terminator as "found" in reject. The
	 * function must stop at the terminator and return the full length,
	 * never scanning past it.
	 */
	KUNIT_EXPECT_EQ(test, strcspn("abc", ""), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyz"), (size_t)3);
}

static void strcspn_stops_at_string_terminator(struct kunit *test)
{
	/* Bytes after the terminator must not influence the result. */
	static const char buf[] = { 'a', 'b', 'c', '\0', 'x', 'y', '\0' };

	KUNIT_EXPECT_EQ(test, strcspn(buf, "x"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "y"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "xy"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "c"), (size_t)2);
}

static void strcspn_reject_terminator_ignored(struct kunit *test)
{
	/* Bytes after the reject terminator must not be part of the set. */
	static const char rej[] = { 'q', '\0', 'a', 'b', '\0' };

	KUNIT_EXPECT_EQ(test, strcspn("abc", rej), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abq", rej), (size_t)2);
}

static void strcspn_embedded_nul_in_string(struct kunit *test)
{
	/* String literal with an embedded NUL: scanning ends there. */
	KUNIT_EXPECT_EQ(test, strcspn("ab\0cd", "d"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\0cd", "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\0cd", "b"), (size_t)1);
}

/* ---- Special byte values ------------------------------------------------ */

static void strcspn_whitespace_and_control_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("foo bar", " \t\n"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("foo\tbar", " \t\n"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("foo\nbar", " \t\n"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("\tfoo", " \t\n"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("foobar", " \t\n"), (size_t)6);
}

static void strcspn_high_bit_bytes(struct kunit *test)
{
	/* Bytes >= 0x80 must compare correctly (no sign-extension issues). */
	static const char s[] = { 'a', 'b', (char)0xff, 'c', '\0' };
	static const char r1[] = { (char)0xff, '\0' };
	static const char r2[] = { (char)0x80, '\0' };
	static const char s2[] = { (char)0x80, (char)0xfe, 'z', '\0' };

	KUNIT_EXPECT_EQ(test, strcspn(s, r1), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s, r2), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn(s, "c"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(s2, "z"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s2, r2), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn(s2, r1), (size_t)3);
}

static void strcspn_digits_and_punctuation(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("a,b;c", ";,"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("12345", "0123456789"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc123", "0123456789"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("/usr/lib", "/"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("usr/lib", "/"), (size_t)3);
}

/* ---- Longer inputs and exhaustive position sweep ------------------------ */

static void strcspn_long_string(struct kunit *test)
{
	char buf[257];
	int i;

	for (i = 0; i < 256; i++)
		buf[i] = 'a';
	buf[256] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)256);
	KUNIT_EXPECT_EQ(test, strcspn(buf, ""), (size_t)256);

	buf[255] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)255);

	buf[128] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)128);

	buf[0] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)0);
}

static void strcspn_every_position_sweep(struct kunit *test)
{
	/*
	 * For each position i in a 32-byte string of 'a', place a single 'z'
	 * at i and check strcspn returns exactly i. Catches any systematic
	 * off-by-one.
	 */
	char buf[33];
	int i, j;

	for (i = 0; i < 32; i++) {
		for (j = 0; j < 32; j++)
			buf[j] = 'a';
		buf[32] = '\0';
		buf[i] = 'z';
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, "z"), (size_t)i,
				    "marker at index %d", i);
	}
}

static void strcspn_every_length_no_match(struct kunit *test)
{
	/* For each length n, a string with no reject bytes returns n. */
	char buf[33];
	int n, j;

	for (n = 0; n <= 32; n++) {
		for (j = 0; j < n; j++)
			buf[j] = 'a';
		buf[n] = '\0';
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, "z"), (size_t)n,
				    "length %d", n);
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, ""), (size_t)n,
				    "length %d, empty reject", n);
	}
}

static void strcspn_all_byte_values_in_reject(struct kunit *test)
{
	/*
	 * Reject set holds every non-NUL byte value. Any non-empty string
	 * must then return 0; the empty string returns 0 as well.
	 */
	char rej[256];
	char s[2];
	int c;

	for (c = 1; c < 256; c++)
		rej[c - 1] = (char)c;
	rej[255] = '\0';

	s[1] = '\0';
	for (c = 1; c < 256; c++) {
		s[0] = (char)c;
		KUNIT_EXPECT_EQ_MSG(test, strcspn(s, rej), (size_t)0,
				    "byte 0x%02x", c);
	}
	KUNIT_EXPECT_EQ(test, strcspn("", rej), (size_t)0);
}

static void strcspn_each_byte_absent_from_reject(struct kunit *test)
{
	/*
	 * Reject set holds every non-NUL byte except one; a 1-byte string
	 * made of that excluded byte returns 1.
	 */
	char rej[256];
	char s[2];
	int c, k, idx;

	s[1] = '\0';
	for (c = 1; c < 256; c += 17) {
		idx = 0;
		for (k = 1; k < 256; k++) {
			if (k != c)
				rej[idx++] = (char)k;
		}
		rej[idx] = '\0';
		s[0] = (char)c;
		KUNIT_EXPECT_EQ_MSG(test, strcspn(s, rej), (size_t)1,
				    "excluded byte 0x%02x", c);
	}
}

/* ---- Relationship with other string functions --------------------------- */

static void strcspn_consistent_with_strpbrk(struct kunit *test)
{
	static const char *const strings[] = {
		"", "a", "hello", "hello world", "a,b;c", "mississippi",
	};
	static const char *const rejects[] = {
		"", "a", "l", "o", " ", ";,", "xyz", "ipm",
	};
	int i, j;

	for (i = 0; i < ARRAY_SIZE(strings); i++) {
		for (j = 0; j < ARRAY_SIZE(rejects); j++) {
			const char *s = strings[i];
			const char *r = rejects[j];
			const char *hit = strpbrk(s, r);
			size_t expected = hit ? (size_t)(hit - s) : strlen(s);

			KUNIT_EXPECT_EQ_MSG(test, strcspn(s, r), expected,
					    "s=\"%s\" reject=\"%s\"", s, r);
		}
	}
}

static void strcspn_result_never_exceeds_strlen(struct kunit *test)
{
	static const char *const strings[] = {
		"", "x", "ab", "hello", "the quick brown fox",
	};
	static const char *const rejects[] = {
		"", "x", "e", "q", "zzz", "abcdefghijklmnopqrstuvwxyz",
	};
	int i, j;

	for (i = 0; i < ARRAY_SIZE(strings); i++) {
		for (j = 0; j < ARRAY_SIZE(rejects); j++) {
			size_t n = strcspn(strings[i], rejects[j]);

			KUNIT_EXPECT_LE_MSG(test, n, strlen(strings[i]),
					    "s=\"%s\" reject=\"%s\"",
					    strings[i], rejects[j]);
			/* The byte at the returned index is NUL or rejected. */
			if (n < strlen(strings[i]))
				KUNIT_EXPECT_NOT_NULL_MSG(test,
					strchr(rejects[j], strings[i][n]),
					"s=\"%s\" reject=\"%s\" n=%zu",
					strings[i], rejects[j], n);
			else
				KUNIT_EXPECT_EQ(test, strings[i][n], '\0');
		}
	}
}

static void strcspn_prefix_has_no_rejected_bytes(struct kunit *test)
{
	static const char *const strings[] = {
		"hello world", "abcabcabc", "the quick brown fox",
	};
	static const char *const rejects[] = {
		"o", "c", "k", " ", "xyz", "abc",
	};
	int i, j;
	size_t k;

	for (i = 0; i < ARRAY_SIZE(strings); i++) {
		for (j = 0; j < ARRAY_SIZE(rejects); j++) {
			size_t n = strcspn(strings[i], rejects[j]);

			for (k = 0; k < n; k++)
				KUNIT_EXPECT_NULL_MSG(test,
					strchr(rejects[j], strings[i][k]),
					"s=\"%s\" reject=\"%s\" k=%zu",
					strings[i], rejects[j], k);
		}
	}
}

